action.command:
pwsh -NoProfile -Command "
$input_json = $null
try { $input_json = $input | ConvertFrom-Json -ErrorAction Stop } catch {}

# 保存されたファイルパスを取得（stdin JSON の filePath フィールド）
$filePath = if ($input_json -and $input_json.filePath) { $input_json.filePath } else { '' }

if (-not $filePath) {
    Write-Host '[PHP Hook] ファイルパスを取得できませんでした。スキップします。'
    exit 0
}

Write-Host "[PHP Hook] 構文チェック中: $filePath"

# ── Step 1: php -l による構文チェック ──────────────────────────
$lintResult = & php -l $filePath 2>&1
$lintExit   = $LASTEXITCODE

if ($lintExit -ne 0) {
    # 構文エラーあり: エラー内容を stderr に出力して終了コード 2 で終了
    $errorText = $lintResult -join "`n"
    Write-Error "[PHP Syntax Error] $filePath`n$errorText"
    exit 2
}

Write-Host '[PHP Hook] 構文チェック: OK'

# ── Step 2: テストスイートの実行 ────────────────────────────────
# このプロジェクトは composer を使用しないため vendor/bin/phpunit は存在しない。
# tests/run.php が存在すればそれを実行し、なければスキップする。

$projectRoot = Split-Path -Parent (Split-Path -Parent $filePath)

$phpunit   = Join-Path $projectRoot 'vendor/bin/phpunit'
$testScript = Join-Path $projectRoot 'tests/run.php'

if (Test-Path $phpunit) {
    Write-Host '[PHP Hook] PHPUnit を実行中...'
    $testResult = & php $phpunit --colors=never 2>&1
    $testExit   = $LASTEXITCODE
} elseif (Test-Path $testScript) {
    Write-Host '[PHP Hook] tests/run.php を実行中...'
    $testResult = & php $testScript 2>&1
    $testExit   = $LASTEXITCODE
} else {
    Write-Host '[PHP Hook] テストスイートが見つかりません。スキップします。'
    exit 0
}

if ($testExit -ne 0) {
    $errorText = $testResult -join "`n"
    Write-Error "[PHP Test Failure] テストが失敗しました。`n$errorText"
    exit 2
}

Write-Host '[PHP Hook] すべてのテストが成功しました。'
exit 0
"
